# Purpose: Switch-Wildcard — General-purpose PowerShell utilities.
$filepath = "C:\PShell\Labs\Lab_15\OriginalFiles"$archivePath = "$filepath\Archive\"if (Test-Path $filepath) {  if (-NOT (Test-Path $archivepath))   {    New-Item -Path $filepath -Name "Archive" -ItemType Directory        "2012","2013","KEEP" |     ForEach-Object {New-Item -Path $archivepath -Name $_ -ItemType Directory}  }  switch -WildCard (Get-ChildItem "$filepath\*.log")  {    *2012*  { Move-Item   $_  -Destination $archivePath\2012 -Verbose -Force}    *2013*  { Move-Item   $_  -Destination $archivePath\2013 -Verbose -Force}    *KEEP*  { Move-Item   $_  -Destination $archivePath\KEEP -Verbose -Force}    default { Remove-Item $_  -Verbose -Force}  }}else { write-output "Not Found: $filepath"} 